import{_ as a,o as s,c as o,af as e}from"./chunks/framework.B28LkSoM.js";const g=JSON.parse('{"title":"AI大模型与AI应用","description":"AI、AI 大模型（LLM）、AI 应用三个核心概念的区分，以及 AI 应用开发的整体学习路线","frontmatter":{"title":"AI大模型与AI应用","published":"2026-09-18T00:00:00.000Z","description":"AI、AI 大模型（LLM）、AI 应用三个核心概念的区分，以及 AI 应用开发的整体学习路线","tags":["AI","Python"],"image":"https://img.tsh520.cn/file/blog/post-covers/python-27-llm.webp","order":27,"date":"2026-09-18T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Python学习笔记/27-AI大模型与AI应用.md","filePath":"posts/学习文档/Python学习笔记/27-AI大模型与AI应用.md"}'),l={name:"posts/学习文档/Python学习笔记/27-AI大模型与AI应用.md"};function r(i,t,n,d,p,h){return s(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789689600000"},[...t[0]||(t[0]=[e(`<h2 id="三个概念的层次关系" tabindex="-1">三个概念的层次关系 <a class="header-anchor" href="#三个概念的层次关系" aria-label="Permalink to &quot;三个概念的层次关系&quot;">​</a></h2><p>三者是<strong>层层嵌套</strong>的关系：AI 是最大的学科，AI 大模型是其中的一个技术分支，AI 应用是把大模型落地到具体业务场景的产物。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI（人工智能，学科统称）</span></span>
<span class="line"><span> └── AI 大模型（LLM，技术分支）</span></span>
<span class="line"><span>      └── AI 应用（产品/服务，落地场景）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>概念</th><th>定义</th></tr></thead><tbody><tr><td>AI（人工智能，Artificial Intelligence）</td><td>一个学科领域的统称，目标是使机器能够像人类一样思考、学习、推理和解决问题</td></tr><tr><td>AI 大模型（大语言模型，Large Language Models，LLM）</td><td>AI 技术的一个分支。本质是一个<strong>用代码模拟人脑神经网络</strong>的程序（参数量极其庞大，通常达到数十亿至数千亿级别），通过大量数据训练后，具备理解人类语言、思考、推理并输出人类语言的能力</td></tr><tr><td>AI 应用</td><td>将 AI 大模型技术落地到具体的业务场景中，用来解决实际问题的产品或者服务</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>大模型的&quot;大&quot;指的是<strong>参数量的量级</strong>（数十亿～数千亿），不是指代码量或数据条数。参数就是神经网络里那些可调节的权重。</p></div><h2 id="主流大模型与厂商" tabindex="-1">主流大模型与厂商 <a class="header-anchor" href="#主流大模型与厂商" aria-label="Permalink to &quot;主流大模型与厂商&quot;">​</a></h2><table tabindex="0"><thead><tr><th>厂商</th><th>大模型</th></tr></thead><tbody><tr><td>OpenAI</td><td>GPT</td></tr><tr><td>Google</td><td>Gemini</td></tr><tr><td>深度求索</td><td>DeepSeek</td></tr><tr><td>阿里巴巴</td><td>Qwen（通义千问）</td></tr></tbody></table><h2 id="生活中的-ai-应用" tabindex="-1">生活中的 AI 应用 <a class="header-anchor" href="#生活中的-ai-应用" aria-label="Permalink to &quot;生活中的 AI 应用&quot;">​</a></h2><p>判断标准很简单：<strong>它是不是把大模型能力用到了具体场景里</strong>。例如：</p><ul><li>AI 对话助手（豆包等），可写作文、写代码、生成图像</li><li>政务智能问答：浙江政务服务网办事服务智能问答，问&quot;买房后怎么提取公积金&quot;能直接列出办理事项</li><li>视频内容理解：百度网盘&quot;AI 看视频&quot;，自动生成摘要和分段总结</li><li>数字人直播：慧播星用数字人主播做直播带货</li><li>AI 生成图像：短剧/故事配图</li><li>电商导购：京东 AI 助手按用户描述推荐商品</li></ul><p><img src="https://img.tsh520.cn/file/blog/article/doubao-chat.png" alt="豆包：AI 对话助手"></p><p><img src="https://img.tsh520.cn/file/blog/article/gov-smart-qa.png" alt="浙江政务服务网的办事服务智能问答：AI 应用在政务场景的落地"></p><h2 id="ai-应用开发要学什么" tabindex="-1">AI 应用开发要学什么 <a class="header-anchor" href="#ai-应用开发要学什么" aria-label="Permalink to &quot;AI 应用开发要学什么&quot;">​</a></h2><p>本课程把 AI 应用开发拆成三块：</p><table tabindex="0"><thead><tr><th>模块</th><th>内容</th></tr></thead><tbody><tr><td>AI 应用-基础</td><td>初识 AI、大模型部署、大模型调用（网络基础知识、Apifox 测试、代码调用测试）、提示词工程</td></tr><tr><td>AI 应用-实战</td><td>Streamlit 构建页面、AI 智能伴侣（基本交互、会话记忆、会话管理）</td></tr><tr><td>AI 应用-知识扩展</td><td>文件操作等补充知识</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p>做 AI 应用开发<strong>不需要自己训练大模型</strong>。我们的角色是&quot;调用方&quot;：通过 API 把大模型的能力接进自己的程序，把精力花在业务逻辑和交互体验上。</p></div><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/python学习笔记/28-大模型部署的三种方式/">大模型部署的三种方式</a></li><li><a href="/posts/编程学习/python学习笔记/33-python调用大模型-openai库/">Python 调用大模型（openai 库）</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>AI 是 <code>Artificial Intelligence</code> 的缩写，中文叫<strong>人工智能</strong></li><li>LLM 的全称是 <strong>Large Language Models</strong>，中文叫<strong>大语言模型</strong></li><li>大模型的&quot;大&quot;指的是<strong>参数量</strong>极其庞大（数十亿～数千亿级别）</li><li>大模型的本质：一个用代码模拟<strong>人脑神经网络</strong>的程序，通过大量数据训练后具备理解与生成人类语言的能力</li><li>把大模型技术落地到具体业务场景、解决实际问题的产品或服务，叫 <strong>AI 应用</strong></li><li>主流大模型：OpenAI 的 <strong>GPT</strong>、Google 的 <strong>Gemini</strong>、深度求索的 <strong>DeepSeek</strong>、阿里巴巴的 <strong>Qwen</strong></li><li>做 AI 应用开发，<strong>不需要</strong>自己训练大模型</li><li>判断一个东西是不是 AI 应用，标准就一条：<strong>它是不是把大模型能力用到了具体场景里</strong>（如豆包对话、政务智能问答、网盘&quot;AI 看视频&quot;、数字人直播）</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1</strong> 用一句话说清 AI、AI 大模型、AI 应用三者的层次关系</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按&quot;最大的学科 → 其中一条技术分支 → 落到具体场景的产品&quot;这个从大到小的顺序说</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> AI 是一个学科领域；AI 大模型是它下面的一个技术分支；AI 应用是把大模型的能力落地到具体业务场景后做出的产品或服务。</p></details></li><li><p>[ ] <strong>2-2</strong> 举出 3 个你见过的 AI 应用，并说出它把大模型能力用在了什么场景</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：挑自己真的用过的（聊天助手、办事问答、视频总结、导购……），每个都说清&quot;大模型在里面干了什么活&quot;</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> （举出自己见过的即可，参考）</p><ul><li>豆包：AI 对话助手，写作文、写代码、生成图像</li><li>浙江政务服务网智能问答：办事咨询</li><li>百度网盘&quot;AI 看视频&quot;：视频摘要与分段总结</li></ul></details></li><li><p>[ ] <strong>2-3</strong> 本章的学习路线分成哪三块？（提示：基础 / 实战 / 知识扩展）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按&quot;先学会调（基础）→ 再做出东西（实战）→ 补充周边知识（扩展）&quot;的顺序回忆表格里的三行</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> AI 应用-基础（大模型部署、大模型调用、提示词工程）、AI 应用-实战（Streamlit 构建页面 + AI 智能伴侣）、AI 应用-知识扩展。</p></details></li></ul>`,23)])])}const u=a(l,[["render",r]]);export{g as __pageData,u as default};
